(() => {
'use strict';
const SUBMODULES = {
defenseSecurityOverview: { tab: 'overview', path: '/defense-security', label: 'Tổng quan QP-AN', icon: 'fa-chart-pie' },
defenseSecurityNvqs: { tab: 'nvqs', path: '/defense-security/nvqs', label: 'Nghĩa vụ quân sự', icon: 'fa-person-military-rifle' },
defenseSecurityMilitia: { tab: 'militia', path: '/defense-security/militia', label: 'Dân quân tự vệ', icon: 'fa-people-group' },
defenseSecurityForce: { tab: 'security_force', path: '/defense-security/security-force', label: 'ANTT cơ sở', icon: 'fa-user-shield' },
defenseSecurityRecords: { tab: 'security_records', path: '/defense-security/security-records', label: 'Theo dõi ANTT', icon: 'fa-eye' },
defenseSecurityIncidents: { tab: 'incidents', path: '/defense-security/incidents', label: 'Vụ việc ANTT', icon: 'fa-triangle-exclamation' }
};
const TAB_TO_MODULE = Object.fromEntries(Object.entries(SUBMODULES).map(([key, value]) => [value.tab, key]));
const state = { tab: 'overview', listTab: 'nvqs', page: 1, pageSize: 20, sort: '', direction: 'ASC', catalogs: null, metric: '', metricLabel: '' };
const API = '/api/defense-security';
const KPI_GROUPS = [
{ key: 'nvqs', title: 'NVQS', items: [
{ label: 'Sắp đến tuổi đăng ký NVQS', path: ['nvqs', 'warning_age'], icon: 'fa-user-clock', tone: 'warning' },
{ label: 'Đến tuổi đăng ký NVQS', path: ['nvqs', 'registration_age'], icon: 'fa-id-card', tone: 'blue' },
{ label: 'Theo dõi tuyển quân', path: ['nvqs', 'tracking_age'], icon: 'fa-users-viewfinder', tone: 'blue' },
{ label: 'Chưa đăng ký NVQS', path: ['nvqs', 'unregistered'], icon: 'fa-triangle-exclamation', tone: 'danger' },
{ label: 'Chưa cập nhật sơ tuyển', path: ['nvqs', 'preliminary_missing'], icon: 'fa-clipboard-question', tone: 'warning' },
{ label: 'Chưa cập nhật khám tuyển', path: ['nvqs', 'medical_missing'], icon: 'fa-stethoscope', tone: 'warning' },
{ label: 'Đã nhập ngũ', path: ['nvqs', 'enlisted'], icon: 'fa-person-military-rifle', tone: 'success' },
{ label: 'Đang tại ngũ', path: ['nvqs', 'active_service'], icon: 'fa-shield', tone: 'success' }
] },
{ key: 'militia', title: 'Dân quân tự vệ', items: [
{ label: 'Tổng dân quân', path: ['militia', 'total'], icon: 'fa-people-group', tone: 'neutral' },
{ label: 'Dân quân đang tham gia', path: ['militia', 'active'], icon: 'fa-user-check', tone: 'success' }
] },
{ key: 'security-force', title: 'ANTT cơ sở', items: [
{ label: 'Tổng ANTT cơ sở', path: ['security_force', 'total'], icon: 'fa-shield-halved', tone: 'neutral' },
{ label: 'ANTT đang hoạt động', path: ['security_force', 'active'], icon: 'fa-user-shield', tone: 'success' }
] }
];
let lastPlatformNavigationAt = 0;
let syncingBrowserRoute = false;
const $ = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[c]));
const fmt = value => new Intl.NumberFormat('vi-VN').format(Number(value || 0));
const token = () => (window.App && App.token) || localStorage.getItem(tenantStorageKey('token')) || '';
const csrf = () => (window.App && App.csrfToken) || localStorage.getItem(tenantStorageKey('csrf')) || '';
document.addEventListener('DOMContentLoaded', boot);
window.addEventListener('popstate', handleRoutePopstate);
document.addEventListener('tenant:app-state-change', event => {
if (syncingBrowserRoute) return;
const detail = event.detail || {};
if (detail.screenId === 'defenseSecurity' || SUBMODULES[detail.moduleKey]) {
lastPlatformNavigationAt = Date.now();
syncBrowserRoute(detail);
syncTabFromRoute(detail);
loadAll({ preserveState: true });
}
});
document.addEventListener('tenant:screen-change', event => {
const detail = event.detail || {};
if (detail.screen === 'defenseSecurity') {
if (Date.now() - lastPlatformNavigationAt < 1000) return;
syncTabFromRoute(detail);
loadAll({ preserveState: true });
}
});
function boot() {
registerPlatformModule();
registerActions();
ensureModal();
bindForm();
bindCitizenSearch();
syncTabFromRoute();
$('#defenseYearFilter') && ($('#defenseYearFilter').value = new Date().getFullYear());
$('#defenseYearFilter')?.addEventListener('change', () => { state.page = 1; loadAll({ preserveState: true }); });
$('#defensePageSize')?.addEventListener('change', () => { state.page = 1; loadList(); });
if (isActive()) loadAll();
}
function registerPlatformModule() {
const platform = window.TenantAppPlatform;
if (!platform?.modules) return;
Object.entries(SUBMODULES).forEach(([moduleKey, cfg]) => {
platform.modules.upsert({ moduleKey, screenId: 'defenseSecurity', path: cfg.path, label: cfg.label, mobileLabel: cfg.label, icon: cfg.icon, permissionScope: 'defense_security' });
platform.routes?.upsert?.({ path: cfg.path, moduleKey, screenId: 'defenseSecurity', action: 'list' });
});
platform.routes?.upsert?.({ path: '/defense-security/overview', moduleKey: 'defenseSecurityOverview', screenId: 'defenseSecurity', action: 'list' });
platform.menus?.upsert?.({ key: 'defense', label: 'Quốc phòng - An ninh', icon: 'fa-shield-halved', items: Object.keys(SUBMODULES) });
platform.menuRenderer?.renderAll?.();
}
function registerActions() {
const actions = window.TenantAppPlatform?.actions;
if (!actions?.register) return;
actions.register('defenseSecurity.search', () => { state.page = 1; loadList(); });
actions.register('defenseSecurity.reset', resetFilters);
actions.register('defenseSecurity.metric', ctx => selectMetric(ctx.target?.closest('[data-defense-kpi]') || ctx));
actions.register('defenseSecurity.create', () => openForm());
actions.register('defenseSecurity.createForCitizen', ctx => openForm({ citizen_id: ctx.dataset.citizenId, full_name: ctx.dataset.label || '', address: ctx.dataset.address || '', recruitment_year: $('#defenseYearFilter')?.value || new Date().getFullYear() }));
actions.register('defenseSecurity.edit', ctx => edit(ctx.dataset.id));
actions.register('defenseSecurity.delete', ctx => remove(ctx.dataset.id));
actions.register('defenseSecurity.page', ctx => page(ctx.dataset.direction));
actions.register('defenseSecurity.selectCitizen', ctx => selectCitizen(ctx.target?.closest('[data-citizen-id]') || ctx.target));
actions.register('defenseSecurity.clearCitizen', clearCitizenSelection);
actions.register('defenseSecurity.export', ctx => downloadReport(ctx.dataset.format || 'excel'));
actions.register('defenseSecurity.print', () => openReport(true));
document.addEventListener('keydown', event => {
const card = event.target?.closest?.('[data-platform-action="defenseSecurity.metric"]');
if (!card || !['Enter', ' '].includes(event.key)) return;
event.preventDefault();
selectMetric(card);
});
}
function isActive() { return $('#defenseSecurityScreen')?.classList.contains('active'); }
async function api(url, options = {}) {
const headers = { Accept: 'application/json' };
if (options.body) headers['Content-Type'] = 'application/json';
if (token()) headers.Authorization = 'Bearer ' + token();
if (csrf()) headers['X-CSRF-Token'] = csrf();
const res = await fetch(url, { method: options.method || 'GET', headers, body: options.body ? JSON.stringify(options.body) : undefined, cache: 'no-store' });
const json = await res.json().catch(() => null);
if (!res.ok || !json?.ok) throw new Error(json?.error?.message || 'Không tải được dữ liệu Quốc phòng - An ninh');
return unwrap(json);
}
function unwrap(payload) {
if (payload && payload.ok !== undefined && payload.data !== undefined) return unwrap(payload.data);
return payload || {};
}
async function loadAll(options = {}) {
if (!$('#defenseSecurityScreen')) return;
if (!options.preserveState) syncTabFromRoute();
renderMode();
try {
if (!state.catalogs) await loadCatalogs();
await loadDashboard();
await loadList();
} catch (error) { toast(error.message, 'danger'); }
}
function matchingSubmoduleForPath(path) {
const normalized = String(path || '').replace(/\/+$/, '') || '/';
return Object.entries(SUBMODULES).find(([, cfg]) => (cfg.path.replace(/\/+$/, '') || '/') === normalized)?.[0] || (normalized === '/defense-security/overview' ? 'defenseSecurityOverview' : '');
}
function syncPlatformRouteFromLocation(source = 'location') {
const path = window.location?.pathname || '';
const moduleKey = matchingSubmoduleForPath(path);
if (!moduleKey) return false;
const current = window.TenantAppPlatform?.navigation?.current?.() || {};
if (current.route === path && current.moduleKey === moduleKey) return true;
const navigate = window.TenantAppPlatform?.navigation?.navigate;
if (typeof navigate === 'function') {
navigate(path, { source });
return true;
}
syncTabFromRoute({ route: path, moduleKey });
loadAll({ preserveState: true });
return true;
}
function handleRoutePopstate() {
syncPlatformRouteFromLocation('popstate');
}
function syncBrowserRoute(detail = {}) {
const route = detail.route || '';
if (!route || !window.location || window.location.pathname === route) return;
const state = { route, moduleKey: detail.moduleKey || '', screenId: detail.screenId || 'defenseSecurity', action: detail.action || 'list', params: detail.params || {} };
syncingBrowserRoute = true;
try {
const historyService = window.TenantAppPlatform?.history;
if (historyService?.push) historyService.push(route, state);
else if (window.history?.pushState) window.history.pushState(state, '', route);
} finally {
syncingBrowserRoute = false;
}
}
function syncTabFromRoute(detail = {}) {
const previous = state.tab;
const current = window.TenantAppPlatform?.navigation?.current?.() || {};
const moduleKey = detail.moduleKey || detail.module || current.moduleKey || '';
if (SUBMODULES[moduleKey]) {
state.tab = SUBMODULES[moduleKey].tab;
if (state.tab !== previous && state.tab !== 'overview') clearMetric();
return;
}
const route = detail.route || current.route || '';
const path = route || window.location?.pathname || '';
const found = Object.values(SUBMODULES).find(cfg => cfg.path === path) || (path === '/defense-security/overview' ? SUBMODULES.defenseSecurityOverview : null);
state.tab = found ? found.tab : 'overview';
if (state.tab !== previous && state.tab !== 'overview') clearMetric();
}
function currentModule() { return SUBMODULES[TAB_TO_MODULE[state.tab] || 'defenseSecurityOverview']; }
function renderMode() {
const cfg = currentModule();
$('#defensePageTitle') && ($('#defensePageTitle').textContent = cfg.label);
$('#defensePageSubtitle') && ($('#defensePageSubtitle').textContent = subtitleForTab());
const isOverview = state.tab === 'overview';
$('#defenseSecurityDashboard')?.classList.toggle('d-none', !isOverview);
$('#defenseListToolbar')?.classList.remove('d-none');
$('#defenseListCard')?.classList.remove('d-none');
$('#defenseStatusFilter')?.closest('.col-md-3')?.classList.remove('d-none');
$('#defenseSearch')?.closest('.col-md-4')?.classList.remove('d-none');
$('#defensePageActions')?.classList.toggle('d-none', isOverview);
}
function subtitleForTab() {
if (state.tab === 'overview') return 'Theo dõi tổng hợp nghĩa vụ quân sự, dân quân tự vệ, ANTT cơ sở, hồ sơ theo dõi và vụ việc ANTT.';
if (state.tab === 'nvqs') return 'Quản lý công dân trong độ tuổi, đăng ký, sơ tuyển, khám tuyển, nhập ngũ, tại ngũ và xuất ngũ.';
if (state.tab === 'militia') return 'Quản lý danh sách dân quân tự vệ, lực lượng, chức vụ, đơn vị, thời gian và trạng thái tham gia.';
if (state.tab === 'security_force') return 'Quản lý lực lượng tham gia bảo vệ ANTT ở cơ sở theo tổ, chức vụ và khu vực phụ trách.';
if (state.tab === 'security_records') return 'Quản lý tiền án, tiền sự và các trường hợp cần chú ý về ANTT theo hồ sơ nhân khẩu.';
return 'Ghi nhận, theo dõi và xử lý các vụ việc ANTT xảy ra trên địa bàn.';
}
function navigateToTab(tab) {
clearMetric();
const moduleKey = TAB_TO_MODULE[tab] || 'defenseSecurityNvqs';
const cfg = SUBMODULES[moduleKey];
const navigate = window.TenantAppNavigationController?.navigate || window.TenantAppPlatform?.navigation?.navigate;
if (typeof navigate === 'function') navigate.call(window.TenantAppNavigationController || window.TenantAppPlatform.navigation, cfg.path);
else {
syncBrowserRoute({ route: cfg.path, moduleKey, screenId: 'defenseSecurity', action: 'list', params: {} });
syncTabFromRoute({ route: cfg.path, moduleKey });
loadAll({ preserveState: true });
}
}
async function loadCatalogs() {
state.catalogs = await api(API + '/catalogs');
fillStatusFilter();
}
function fillStatusFilter() {
const select = $('#defenseStatusFilter');
if (!select || !state.catalogs) return;
const tab = effectiveListTab();
const items = tab === 'nvqs' ? state.catalogs.nvqs_eligibility_statuses : (tab === 'militia' ? state.catalogs.participation_statuses : (tab === 'security_force' ? state.catalogs.security_statuses : (tab === 'security_records' ? state.catalogs.security_record_statuses : state.catalogs.incident_statuses)));
select.innerHTML = '<option value="">Tất cả</option>' + (items || []).map(item => '<option value="' + esc(item.value) + '">' + esc(item.label) + '</option>').join('');
}
async function loadDashboard() {
const data = await api(API + '/dashboard?' + baseQuery(false));
const source = { nvqs: data.nvqs || {}, militia: data.militia || {}, security_force: data.security_force || {} };
$('#defenseSecurityDashboard').innerHTML = KPI_GROUPS.map(group => '<section class="defense-kpi-group defense-kpi-group-' + esc(group.key || 'default') + '" style="--kpi-count:' + esc(group.items.length) + '"><h3>' + esc(group.title) + '</h3><div class="defense-kpi-row">' + group.items.map(item => {
const [tab, metric] = item.path;
return kpiCard(item.label, source[tab]?.[metric] ?? 0, '', item.icon, item.tone, ' data-platform-action="defenseSecurity.metric" data-defense-kpi="1" data-tab="' + esc(tab) + '" data-metric="' + esc(metric) + '" role="button" tabindex="0" aria-pressed="' + (isMetricActive(tab, metric) ? 'true' : 'false') + '"');
}).join('') + '</div></section>').join('');
}
function kpiCard(label, value, unit, icon, tone, attrs = '') {
return '<article class="dashboard-kpi dashboard-tone-' + esc(tone || 'neutral') + '"' + attrs + ' data-kpi-label="' + esc(label) + '" data-kpi-value="' + esc(value || 0) + '" data-kpi-unit="' + esc(unit || '') + '"><div class="dashboard-kpi-head"><span class="dashboard-kpi-icon" aria-hidden="true"><i class="fa-solid ' + esc(icon || 'fa-chart-simple') + '"></i></span><span class="dashboard-kpi-label">' + esc(label) + '</span></div><div class="dashboard-kpi-value"><strong>' + fmt(value) + '</strong>' + (unit ? '<span class="dashboard-kpi-unit">' + esc(unit) + '</span>' : '') + '</div></article>';
}
async function loadList() {
const endpoint = endpointForTab();
const data = await api(API + endpoint + '?' + baseQuery(true));
$('#defenseTotalCount').textContent = 'Tổng số: ' + fmt(data.total || 0) + ' hồ sơ';
$('#defenseListTitle').textContent = titleForTab();
renderHead();
$('#defenseRows').innerHTML = (data.items || []).map((row, index) => rowHtml(row, index, data)).join('') || '<tr><td colspan="12" class="text-center text-muted py-4">Chưa có hồ sơ phù hợp</td></tr>';
renderPager(data);
}
function renderHead() {
const nvqs = ['STT','Mã NK','Họ tên','Ngày sinh','Mã hộ','Năm','Đăng ký','Sơ tuyển','Khám tuyển','Điều kiện','Tuyển chọn','Thao tác'];
const militia = ['STT','Mã NK','Họ tên','Mã hộ','Loại','Chức vụ','Đơn vị/tổ','Ngày tham gia','Huấn luyện','Trạng thái','Thao tác'];
const security = ['STT','Mã NK','Họ tên','Mã hộ','Tổ ANTT','Chức vụ','Khu vực','Ngày tham gia','Trạng thái','Thao tác'];
const records = ['STT','Mã NK','Họ tên','Mã hộ','Loại hồ sơ','Phân loại','Trạng thái','Rà soát tiếp','Nội dung','Thao tác'];
const incidents = ['STT','Mã vụ việc','Ngày','Loại vụ việc','Địa điểm','Trạng thái','Người trình báo','Nội dung','Thao tác'];
const tab = effectiveListTab();
const headers = tab === 'nvqs' ? nvqs : (tab === 'militia' ? militia : (tab === 'security_force' ? security : (tab === 'security_records' ? records : incidents)));
$('#defenseTableHead').innerHTML = '<tr>' + headers.map(h => '<th>' + esc(h) + '</th>').join('') + '</tr>';
}
function rowHtml(row, index, data) {
const stt = index + 1 + ((data.page || 1) - 1) * (data.pageSize || 20);
const td = (label, html, className = '') => '<td data-label="' + esc(label) + '"' + (className ? ' class="' + className + '"' : '') + '>' + html + '</td>';
const actions = td('Thao tác', '<button class="btn btn-sm btn-outline-primary" data-platform-action="defenseSecurity.edit" data-id="' + esc(row.id) + '" title="Sửa"><i class="fa-solid fa-pen"></i></button> <button class="btn btn-sm btn-outline-danger" data-platform-action="defenseSecurity.delete" data-id="' + esc(row.id) + '" title="Xóa"><i class="fa-solid fa-trash"></i></button>', 'text-end');
const tab = effectiveListTab();
if (tab === 'nvqs') return '<tr>' + td('STT', stt) + td('Mã NK', esc(row.citizen_code)) + td('Họ tên', esc(row.full_name)) + td('Ngày sinh', esc(formatDate(row.date_of_birth))) + td('Mã hộ', esc(row.household_code)) + td('Năm', esc(row.recruitment_year)) + td('Đăng ký', esc(row.registered_status_label)) + td('Sơ tuyển', esc(row.preliminary_status_label)) + td('Khám tuyển', esc(row.medical_exam_status_label)) + td('Điều kiện', esc(row.eligibility_status_label)) + td('Tuyển chọn', esc(row.selection_status_label)) + actions + '</tr>';
if (tab === 'militia') return '<tr>' + td('STT', stt) + td('Mã NK', esc(row.citizen_code)) + td('Họ tên', esc(row.full_name)) + td('Mã hộ', esc(row.household_code)) + td('Loại', esc(row.militia_type_label)) + td('Chức vụ', esc(row.position_name)) + td('Đơn vị/tổ', esc(row.unit_name)) + td('Ngày tham gia', esc(formatDate(row.joined_date))) + td('Huấn luyện', esc(row.training_result || row.training_name)) + td('Trạng thái', esc(row.participation_status_label)) + actions + '</tr>';
if (tab === 'security_force') return '<tr>' + td('STT', stt) + td('Mã NK', esc(row.citizen_code)) + td('Họ tên', esc(row.full_name)) + td('Mã hộ', esc(row.household_code)) + td('Tổ ANTT', esc(row.team_name)) + td('Chức vụ', esc(row.position_label)) + td('Khu vực', esc(row.area_in_charge)) + td('Ngày tham gia', esc(formatDate(row.joined_date))) + td('Trạng thái', esc(row.participation_status_label)) + actions + '</tr>';
if (tab === 'security_records') return '<tr>' + td('STT', stt) + td('Mã NK', esc(row.citizen_code)) + td('Họ tên', esc(row.full_name)) + td('Mã hộ', esc(row.household_code)) + td('Loại hồ sơ', esc(row.record_type_label)) + td('Phân loại', esc(row.classification)) + td('Trạng thái', esc(row.current_status_label)) + td('Rà soát tiếp', esc(formatDate(row.next_review_date))) + td('Nội dung', esc(row.summary)) + actions + '</tr>';
return '<tr>' + td('STT', stt) + td('Mã vụ việc', esc(row.incident_code)) + td('Ngày', esc(formatDate(row.occurred_date))) + td('Loại vụ việc', esc(row.incident_type_label)) + td('Địa điểm', esc(row.location)) + td('Trạng thái', esc(row.incident_status_label)) + td('Người trình báo', esc(row.reporter_name)) + td('Nội dung', esc(row.summary)) + actions + '</tr>';
}
function baseQuery(withPaging) {
const params = new URLSearchParams();
const year = $('#defenseYearFilter')?.value || new Date().getFullYear();
const search = $('#defenseSearch')?.value?.trim();
const status = $('#defenseStatusFilter')?.value;
const tab = effectiveListTab();
if (year) params.set('year', year);
if (search) params.set('search', search);
if (state.metric) params.set('metric', state.metric);
if (status) params.set(tab === 'nvqs' ? 'eligibility_status' : (tab === 'security_records' ? 'current_status' : (tab === 'incidents' ? 'incident_status' : 'participation_status')), status);
if (state.metric && tab === 'security_records' && ['CRIMINAL_RECORD','ADMINISTRATIVE_RECORD','WATCHLIST'].includes(state.metric)) params.set('record_type', state.metric);
if (state.metric && tab === 'incidents' && ['THEFT','FIGHT','CONFLICT'].includes(state.metric)) params.set('type', state.metric);
if (withPaging) { params.set('page', state.page); params.set('pageSize', $('#defensePageSize')?.value || state.pageSize); if (state.sort) params.set('sort', state.sort); params.set('direction', state.direction); }
return params.toString();
}
function effectiveListTab() { return state.tab === 'overview' ? (state.listTab || 'nvqs') : state.tab; }
function endpointForTab() { const tab = effectiveListTab(); if (tab === 'nvqs') return '/nvqs'; if (tab === 'militia') return '/militia'; if (tab === 'security_force') return '/security-force'; if (tab === 'security_records') return '/security-records'; return '/incidents'; }
function titleForTab() { if (state.metricLabel) return 'Danh sách ' + state.metricLabel; const tab = effectiveListTab(); return tab === 'nvqs' ? 'Danh sách nghĩa vụ quân sự' : (tab === 'militia' ? 'Danh sách dân quân tự vệ' : (tab === 'security_force' ? 'Danh sách ANTT cơ sở' : (tab === 'security_records' ? 'Danh sách theo dõi ANTT' : 'Danh sách vụ việc ANTT'))); }
function isMetricActive(tab, metric) { return state.tab === 'overview' && state.listTab === tab && state.metric === metric; }
function clearMetric() { state.metric = ''; state.metricLabel = ''; state.listTab = state.tab === 'overview' ? 'nvqs' : state.tab; }
function selectMetric(target) {
const tab = target?.dataset?.tab || 'nvqs';
const metric = target?.dataset?.metric || '';
state.tab = 'overview';
state.listTab = tab;
state.metric = metric;
state.metricLabel = target?.dataset?.kpiLabel || target?.getAttribute?.('data-kpi-label') || '';
state.page = 1;
fillStatusFilter();
renderMode();
loadDashboard().catch(error => toast(error.message, 'danger'));
loadList().catch(error => toast(error.message, 'danger'));
}
function switchTab(tab, reload = true) {
state.tab = tab || 'overview';
state.listTab = state.tab === 'overview' ? 'nvqs' : state.tab;
state.page = 1;
state.metric = '';
state.metricLabel = '';
fillStatusFilter();
renderMode();
if (reload && state.tab !== 'overview') loadList();
}
function resetFilters() {
if ($('#defenseYearFilter')) $('#defenseYearFilter').value = new Date().getFullYear();
if ($('#defenseSearch')) $('#defenseSearch').value = '';
if ($('#defenseStatusFilter')) $('#defenseStatusFilter').value = '';
state.metric = '';
state.metricLabel = '';
state.listTab = 'nvqs';
state.page = 1;
loadAll();
}
function ensureModal() {
if ($('#defenseRecordModal')) return;
document.body.insertAdjacentHTML('beforeend', '<div class="modal fade" id="defenseRecordModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-xl modal-dialog-scrollable"><form class="modal-content" id="defenseRecordForm" novalidate><div class="modal-header"><h5 class="modal-title" id="defenseModalTitle">Hồ sơ Quốc phòng - An ninh</h5><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Đóng"></button></div><div class="modal-body"><input type="hidden" name="id"><input type="hidden" name="citizen_id"><div class="row g-3"><div class="col-12 position-relative"><label class="form-label" for="defenseCitizenSearch">Nhân khẩu</label><input id="defenseCitizenSearch" class="form-control" autocomplete="off" placeholder="Nhập họ tên, mã nhân khẩu, mã hộ hoặc năm sinh" required><div id="defenseCitizenSuggestions" class="list-group position-absolute w-100 shadow d-none" style="z-index:1060;max-height:260px;overflow:auto"></div><div id="defenseCitizenSelected" class="form-text"></div></div><div id="defenseDynamicFields" class="row g-3 m-0 p-0"></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Hủy</button><button type="submit" class="btn btn-primary">Lưu</button></div></form></div></div>');
}
function dynamicFields(record = {}) {
if (state.tab === 'nvqs') return [
input('recruitment_year', 'Năm tuyển quân', 'number', record.recruitment_year || $('#defenseYearFilter')?.value || new Date().getFullYear(), 'col-md-3'),
select('registered_status', 'Đã đăng ký NVQS', state.catalogs.yes_no, record.registered_status || 'NO'),
input('registration_date', 'Ngày đăng ký', 'text', formatDate(record.registration_date), 'col-md-3 defense-date'),
select('preliminary_status', 'Sơ tuyển', state.catalogs.nvqs_preliminary_statuses, record.preliminary_status || 'NOT_UPDATED'),
input('preliminary_date', 'Ngày sơ tuyển', 'text', formatDate(record.preliminary_date), 'col-md-3 defense-date'),
select('medical_exam_status', 'Khám tuyển', state.catalogs.nvqs_medical_statuses, record.medical_exam_status || 'NOT_UPDATED'),
input('medical_exam_date', 'Ngày khám', 'text', formatDate(record.medical_exam_date), 'col-md-3 defense-date'),
input('health_classification', 'Phân loại sức khỏe', 'text', record.health_classification || '', 'col-md-3'),
select('eligibility_status', 'Tình trạng điều kiện', state.catalogs.nvqs_eligibility_statuses, record.eligibility_status || 'UNKNOWN'),
input('deferment_reason', 'Lý do tạm hoãn', 'text', record.deferment_reason || '', 'col-md-4'),
input('exemption_reason', 'Lý do miễn', 'text', record.exemption_reason || '', 'col-md-4'),
select('selection_status', 'Tuyển chọn', state.catalogs.nvqs_selection_statuses, record.selection_status || 'NOT_SELECTED'),
checkbox('order_received', 'Đã nhận lệnh nhập ngũ', record.order_received), checkbox('active_service', 'Đang tại ngũ', record.active_service), checkbox('completed_service', 'Đã hoàn thành NVQS', record.completed_service),
input('enlistment_date', 'Ngày nhập ngũ', 'text', formatDate(record.enlistment_date), 'col-md-3 defense-date'), input('enlistment_unit', 'Đơn vị nhập ngũ', 'text', record.enlistment_unit || '', 'col-md-5'), input('discharge_date', 'Ngày xuất ngũ', 'text', formatDate(record.discharge_date), 'col-md-3 defense-date'), input('discharge_unit', 'Đơn vị trước khi xuất ngũ', 'text', record.discharge_unit || '', 'col-md-5'), textarea(record.note || '')
].join('');
if (state.tab === 'militia') return [select('militia_type','Loại/lực lượng dân quân',state.catalogs.militia_types,record.militia_type||'CORE'), input('position_name','Chức vụ','text',record.position_name||'','col-md-4'), input('unit_name','Đơn vị/tổ','text',record.unit_name||'','col-md-4'), input('joined_date','Ngày tham gia','text',formatDate(record.joined_date),'col-md-3 defense-date'), input('ended_date','Ngày kết thúc','text',formatDate(record.ended_date),'col-md-3 defense-date'), input('training_name','Huấn luyện','text',record.training_name||'','col-md-4'), input('training_date','Ngày huấn luyện','text',formatDate(record.training_date),'col-md-3 defense-date'), input('training_result','Kết quả huấn luyện','text',record.training_result||'','col-md-4'), select('participation_status','Trạng thái',state.catalogs.participation_statuses,record.participation_status||'ACTIVE'), input('reason','Lý do','text',record.reason||'','col-md-4'), textarea(record.note||'')].join('');
if (state.tab === 'security_records') return [select('record_type','Loại hồ sơ',state.catalogs.security_record_types,record.record_type||'WATCHLIST'), input('classification','Phân loại','text',record.classification||'','col-md-4'), select('current_status','Trạng thái',state.catalogs.security_record_statuses,record.current_status||'ACTIVE'), input('occurred_date','Ngày phát sinh','text',formatDate(record.occurred_date),'col-md-3 defense-date'), input('next_review_date','Ngày rà soát tiếp','text',formatDate(record.next_review_date),'col-md-3 defense-date'), input('source','Nguồn thông tin','text',record.source||'','col-md-4'), input('decision_number','Số quyết định/bản án','text',record.decision_number||'','col-md-4'), input('issuing_authority','Cơ quan ban hành','text',record.issuing_authority||'','col-md-4'), textareaNamed('summary','Nội dung/lý do',record.summary||''), textareaNamed('measures','Biện pháp đã thực hiện',record.measures||''), textareaNamed('result','Kết quả',record.result||''), textarea(record.note||'')].join('');
if (state.tab === 'incidents') return [input('incident_code','Mã vụ việc','text',record.incident_code||'','col-md-3'), select('incident_type_code','Loại vụ việc',state.catalogs.incident_types,record.incident_type_code||'OTHER'), select('incident_status','Trạng thái',state.catalogs.incident_statuses,record.incident_status||'NEW'), input('occurred_date','Ngày xảy ra','text',formatDate(record.occurred_date),'col-md-3 defense-date'), input('occurred_time','Giờ xảy ra','text',record.occurred_time||'','col-md-3'), input('location','Địa điểm','text',record.location||'','col-md-6'), input('area_code','Khu vực/xóm cũ','text',record.area_code||'','col-md-3'), input('reporter_name','Người trình báo','text',record.reporter_name||'','col-md-4'), input('receiving_agency','Cơ quan tiếp nhận','text',record.receiving_agency||'','col-md-4'), input('estimated_damage','Thiệt hại ước tính','number',record.estimated_damage||'','col-md-3'), textareaNamed('summary','Nội dung vụ việc',record.summary||''), textareaNamed('asset_description','Tài sản liên quan',record.asset_description||''), textareaNamed('handling_direction','Hướng xử lý',record.handling_direction||''), textareaNamed('result','Kết quả',record.result||''), textarea(record.note||'')].join('');
return [input('team_name','Tổ ANTT','text',record.team_name||'','col-md-4'), select('position_code','Chức vụ',state.catalogs.security_positions,record.position_code||'MEMBER'), input('area_in_charge','Khu vực phụ trách','text',record.area_in_charge||'','col-md-4'), input('joined_date','Ngày tham gia','text',formatDate(record.joined_date),'col-md-3 defense-date'), input('ended_date','Ngày kết thúc','text',formatDate(record.ended_date),'col-md-3 defense-date'), select('participation_status','Trạng thái',state.catalogs.security_statuses,record.participation_status||'ACTIVE'), input('reason','Lý do','text',record.reason||'','col-md-4'), textarea(record.note||'')].join('');
}
function input(name, label, type, value, cls = 'col-md-3') { return '<div class="' + cls + '"><label class="form-label">' + esc(label) + '</label><input name="' + esc(name) + '" type="' + type + '" inputmode="' + (cls.includes('defense-date') ? 'numeric' : '') + '" placeholder="' + (cls.includes('defense-date') ? 'dd/mm/yyyy' : '') + '" class="form-control" value="' + esc(value) + '"></div>'; }
function select(name, label, items, value) { return '<div class="col-md-4"><label class="form-label">' + esc(label) + '</label><select name="' + esc(name) + '" class="form-select">' + (items || []).map(item => '<option value="' + esc(item.value) + '" ' + (item.value === value ? 'selected' : '') + '>' + esc(item.label) + '</option>').join('') + '</select></div>'; }
function checkbox(name, label, checked) { return '<div class="col-md-3 d-flex align-items-end"><label class="form-check mb-2"><input class="form-check-input" type="checkbox" name="' + esc(name) + '" value="1" ' + (checked ? 'checked' : '') + '> <span class="form-check-label">' + esc(label) + '</span></label></div>'; }
function textarea(value) { return textareaNamed('note', 'Ghi chú', value); }
function textareaNamed(name, label, value) { return '<div class=\"col-12\"><label class=\"form-label\">' + esc(label) + '</label><textarea name=\"' + esc(name) + '\" class=\"form-control\" rows=\"3\">' + esc(value) + '</textarea></div>'; }
function openForm(record = {}) {
ensureModal();
const form = $('#defenseRecordForm');
form.reset();
form.elements.id.value = record.id || '';
form.elements.citizen_id.value = record.citizen_id || '';
$('#defenseModalTitle').textContent = state.tab === 'nvqs' ? 'Hồ sơ nghĩa vụ quân sự' : (state.tab === 'militia' ? 'Hồ sơ dân quân tự vệ' : (state.tab === 'security_force' ? 'Hồ sơ ANTT cơ sở' : (state.tab === 'security_records' ? 'Hồ sơ theo dõi ANTT' : 'Vụ việc ANTT')));
$('#defenseDynamicFields').innerHTML = dynamicFields(record);
const label = record.full_name ? [record.citizen_code, record.full_name, record.household_code].filter(Boolean).join(' - ') : '';
$('#defenseCitizenSearch').value = label;
setSelectedCitizenText(label, record.address || '');
bootstrap.Modal.getOrCreateInstance($('#defenseRecordModal')).show();
}
async function edit(id) {
if (!id) return;
const endpoint = endpointForTab() + '/';
try { openForm(await api(API + endpoint + encodeURIComponent(id))); } catch (error) { toast(error.message, 'danger'); }
}
function bindForm() {
$('#defenseRecordForm')?.addEventListener('submit', async event => {
event.preventDefault();
const form = event.currentTarget;
const data = Object.fromEntries(new FormData(form).entries());
if (state.tab !== 'incidents' && !data.citizen_id) { toast('Vui lòng chọn nhân khẩu từ danh sách.', 'warning'); $('#defenseCitizenSearch')?.focus(); return; }
try {
normalizeDates(data);
['order_received','active_service','completed_service'].forEach(key => { if (!data[key]) data[key] = 0; });
const id = data.id; delete data.id;
const endpoint = endpointForTab();
await api(API + endpoint + (id ? '/' + encodeURIComponent(id) : ''), { method: id ? 'PUT' : 'POST', body: data });
bootstrap.Modal.getOrCreateInstance($('#defenseRecordModal')).hide();
await loadAll();
toast('Đã lưu hồ sơ Quốc phòng - An ninh');
} catch (error) { toast(error.message, 'danger'); }
});
}
function bindCitizenSearch() {
let timer = null;
document.addEventListener('input', event => {
if (event.target?.id !== 'defenseCitizenSearch') return;
clearTimeout(timer);
$('#defenseRecordForm').elements.citizen_id.value = '';
setSelectedCitizenText('', '');
timer = setTimeout(() => searchCitizens(event.target.value), 250);
});
}
async function searchCitizens(value) {
const box = $('#defenseCitizenSuggestions');
const q = String(value || '').trim();
if (!box) return;
if (q.length < 2) { box.innerHTML = ''; box.classList.add('d-none'); return; }
try {
const data = await api(API + '/citizen-search?q=' + encodeURIComponent(q));
const items = data.items || [];
if (!items.length) { box.innerHTML = '<div class="list-group-item text-muted">Không tìm thấy nhân khẩu phù hợp</div>'; box.classList.remove('d-none'); return; }
box.innerHTML = items.map(row => {
const label = [row.citizen_code, row.full_name, row.household_code].filter(Boolean).join(' - ');
const detail = [formatDate(row.date_of_birth), row.gender, row.address || row.area_code].filter(Boolean).join(' - ');
return '<button type="button" class="list-group-item list-group-item-action" data-platform-action="defenseSecurity.selectCitizen" data-citizen-id="' + esc(row.id) + '" data-label="' + esc(label) + '" data-detail="' + esc(detail) + '"><strong>' + esc(label) + '</strong>' + (detail ? '<br><small>' + esc(detail) + '</small>' : '') + '</button>';
}).join('');
box.classList.remove('d-none');
} catch (error) { box.innerHTML = '<div class="list-group-item text-danger">' + esc(error.message) + '</div>'; box.classList.remove('d-none'); }
}
function selectCitizen(button) {
if (!button?.dataset?.citizenId) return;
$('#defenseRecordForm').elements.citizen_id.value = button.dataset.citizenId;
$('#defenseCitizenSearch').value = button.dataset.label || '';
setSelectedCitizenText(button.dataset.label || '', button.dataset.detail || '');
$('#defenseCitizenSuggestions')?.classList.add('d-none');
}
function clearCitizenSelection() {
const form = $('#defenseRecordForm');
if (form) form.elements.citizen_id.value = '';
if ($('#defenseCitizenSearch')) $('#defenseCitizenSearch').value = '';
setSelectedCitizenText('', '');
$('#defenseCitizenSuggestions')?.classList.add('d-none');
$('#defenseCitizenSearch')?.focus();
}
function setSelectedCitizenText(label, detail) {
const selected = $('#defenseCitizenSelected');
if (!selected) return;
selected.innerHTML = label ? '<span>' + esc([label, detail].filter(Boolean).join(' - ')) + '</span> <button type="button" class="btn btn-link btn-sm p-0 align-baseline" data-platform-action="defenseSecurity.clearCitizen" aria-label="Bỏ chọn nhân khẩu">&times;</button>' : '';
}
async function remove(id) {
if (!id || !confirm('Xóa hồ sơ này?')) return;
const endpoint = endpointForTab() + '/';
try { await api(API + endpoint + encodeURIComponent(id), { method: 'DELETE' }); await loadAll(); toast('Đã xóa hồ sơ'); } catch (error) { toast(error.message, 'danger'); }
}
function page(direction) {
const totalPages = Number($('#defensePager')?.dataset.totalPages || 1);
state.page = direction === 'prev' ? Math.max(1, state.page - 1) : Math.min(totalPages, state.page + 1);
loadList();
}
function renderPager(data) {
const host = $('#defensePager');
if (!host) return;
const totalPages = Number(data.totalPages || 1);
host.dataset.totalPages = String(totalPages);
host.innerHTML = '<button class="btn btn-sm btn-outline-secondary" data-platform-action="defenseSecurity.page" data-direction="prev" ' + (state.page <= 1 ? 'disabled' : '') + '>Trước</button><span>Trang ' + fmt(state.page) + '/' + fmt(totalPages) + '</span><button class="btn btn-sm btn-outline-secondary" data-platform-action="defenseSecurity.page" data-direction="next" ' + (state.page >= totalPages ? 'disabled' : '') + '>Sau</button>';
}
function normalizeDates(data) {
Object.keys(data).forEach(key => { if (key.endsWith('_date')) data[key] = toIsoDate(data[key]); });
}
function toIsoDate(value) {
value = String(value || '').trim();
if (!value) return '';
if (/^\d{4}-\d{2}-\d{2}$/.test(value)) return value;
const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(value);
if (!m) throw new Error('Ngày phải theo định dạng dd/mm/yyyy.');
const day = Number(m[1]), month = Number(m[2]), year = Number(m[3]);
const d = new Date(Date.UTC(year, month - 1, day));
if (d.getUTCFullYear() !== year || d.getUTCMonth() + 1 !== month || d.getUTCDate() !== day) throw new Error('Ngày không hợp lệ.');
return String(year).padStart(4, '0') + '-' + String(month).padStart(2, '0') + '-' + String(day).padStart(2, '0');
}
function formatDate(value) {
value = String(value || '').slice(0, 10);
if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return value || '';
const [y, m, d] = value.split('-');
return d + '/' + m + '/' + y;
}
function currentReportType() {
if (state.tab === 'overview') return 'defense-security-summary';
if (state.tab === 'militia') return 'defense-security-militia';
if (state.tab === 'security_force') return 'defense-security-antt';
if (state.tab === 'security_records') return 'defense-security-security-records';
if (state.tab === 'incidents') return 'defense-security-incidents';
return 'defense-security-nvqs';
}
function downloadReport(format) {
const endpoint = format === 'pdf' ? '/api/reports/export-pdf' : '/api/reports/export-excel';
window.open(endpoint + '?type=' + encodeURIComponent(currentReportType()) + '&' + baseQuery(false), '_blank');
}
function openReport() {
const navigate = window.TenantAppNavigationController?.navigate || window.TenantAppPlatform?.navigation?.navigate;
if (typeof navigate === 'function') navigate.call(window.TenantAppNavigationController || window.TenantAppPlatform.navigation, 'reports');
setTimeout(() => { const select = $('#reportTypeSelect'); if (select) { select.value = currentReportType(); window.loadReport?.(); } }, 150);
}
function toast(message, variant = 'success') {
if (typeof window.showToast === 'function') window.showToast(message, variant);
else console[variant === 'danger' ? 'error' : 'log'](message);
}
})();
